    iron_glassengravingwheel = { name = "Železni rezbarsko kolo za steklo", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni rezbarsko kolo za steklo za steklarje." },
    bronze_glassengravingwheel = { name = "Bronast rezbarsko kolo za steklo", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast rezbarsko kolo za steklo za steklarje." },
    silver_glassengravingwheel = { name = "Srebrn rezbarsko kolo za steklo", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn rezbarsko kolo za steklo za steklarje." },
    gilded_glassengravingwheel = { name = "Pozlačen rezbarsko kolo za steklo", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen rezbarsko kolo za steklo za steklarje." },
    jewel_set_glassengravingwheel = { name = "Draguljast rezbarsko kolo za steklo", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast rezbarsko kolo za steklo za steklarje." },
    royal_sovereign_glassengravingwheel = { name = "Kraljevski suveren rezbarsko kolo za steklo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren rezbarsko kolo za steklo z biseri za krono." },
}
local BUILDINGS = {
    glassengravingwheel_workshop = { name = "Glassengravingwheel delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    glassengravingwheel_house = { name = "Glassengravingwheel hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_glassengravingwheel_atelier = { name = "Mojstrski glassengravingwheel atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_glassengravingwheel_palace = { name = "Suverena glassengravingwheel palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GlassEngravingWheelMaker.ironStock=16; GlassEngravingWheelMaker.bronzeStock=14; GlassEngravingWheelMaker.woodStock=12; GlassEngravingWheelMaker.leatherStock=8; GlassEngravingWheelMaker.silverStock=8; GlassEngravingWheelMaker.goldStock=6; GlassEngravingWheelMaker.jewelStock=4; GlassEngravingWheelMaker.pearlStock=4
GlassEngravingWheelMaker.productStock = {}; GlassEngravingWheelMaker.buildings = {}; GlassEngravingWheelMaker.maker = nil; GlassEngravingWheelMaker.activeMaking = {}; GlassEngravingWheelMaker.totalProducts = 0; GlassEngravingWheelMaker.dayTimer = 0
function GlassEngravingWheelMaker.init() GlassEngravingWheelMaker.ironStock=16; GlassEngravingWheelMaker.bronzeStock=14; GlassEngravingWheelMaker.woodStock=12; GlassEngravingWheelMaker.leatherStock=8; GlassEngravingWheelMaker.silverStock=8; GlassEngravingWheelMaker.goldStock=6; GlassEngravingWheelMaker.jewelStock=4; GlassEngravingWheelMaker.pearlStock=4; GlassEngravingWheelMaker.productStock={}; GlassEngravingWheelMaker.buildings={}; GlassEngravingWheelMaker.maker=nil; GlassEngravingWheelMaker.activeMaking={}; GlassEngravingWheelMaker.totalProducts=0; GlassEngravingWheelMaker.dayTimer=0; print("[GlassEngravingWheelMaker] Royal Glass Engraving Wheel Maker System initialized (6 products, 4 buildings)") end
function GlassEngravingWheelMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassEngravingWheelMaker.maker={name=n or ("Rezbar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rezbar najet: %s (spretnost: %d)",GlassEngravingWheelMaker.maker.name,s),"success") end; return true end
function GlassEngravingWheelMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassEngravingWheelMaker.build(id) local ok,e=GlassEngravingWheelMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassEngravingWheelMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassEngravingWheelMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassEngravingWheelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassEngravingWheelMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassEngravingWheelMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassEngravingWheelMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassEngravingWheelMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassEngravingWheelMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassEngravingWheelMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassEngravingWheelMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassEngravingWheelMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassEngravingWheelMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassEngravingWheelMaker.buildings==0 then return false,"Potrebna rezbarska delavnica" end; if not GlassEngravingWheelMaker.maker then return false,"Potreben rezbar" end; return true end
function GlassEngravingWheelMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassEngravingWheelMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassEngravingWheelMaker.ironStock=GlassEngravingWheelMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassEngravingWheelMaker.bronzeStock=GlassEngravingWheelMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassEngravingWheelMaker.woodStock=GlassEngravingWheelMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassEngravingWheelMaker.leatherStock=GlassEngravingWheelMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassEngravingWheelMaker.silverStock=GlassEngravingWheelMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassEngravingWheelMaker.goldStock=GlassEngravingWheelMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassEngravingWheelMaker.jewelStock=GlassEngravingWheelMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassEngravingWheelMaker.pearlStock=GlassEngravingWheelMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassEngravingWheelMaker.maker then t=math.max(1,t-math.floor(GlassEngravingWheelMaker.maker.skill/13)) end; table.insert(GlassEngravingWheelMaker.activeMaking,{id="glassengravingwheel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassEngravingWheelMaker.completeMaking(m) local q=1.0+(GlassEngravingWheelMaker.getQualityBonus()/100); if GlassEngravingWheelMaker.maker then q=q+(GlassEngravingWheelMaker.maker.skill/140) end; q=math.min(2.5,q); GlassEngravingWheelMaker.productStock[m.productType]=(GlassEngravingWheelMaker.productStock[m.productType] or 0)+m.quantity; GlassEngravingWheelMaker.totalProducts=GlassEngravingWheelMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassEngravingWheelMaker.maker then GlassEngravingWheelMaker.maker.itemsMade=GlassEngravingWheelMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassEngravingWheelMaker.maker.skill=math.min(100,GlassEngravingWheelMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rezbarsko izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassengravingwheel.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassEngravingWheelMaker.update(dt) if not _G.state then return end; GlassEngravingWheelMaker.dayTimer=GlassEngravingWheelMaker.dayTimer+dt; if GlassEngravingWheelMaker.dayTimer>=30 then GlassEngravingWheelMaker.dayTimer=0; for i=#GlassEngravingWheelMaker.activeMaking,1,-1 do local m=GlassEngravingWheelMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassEngravingWheelMaker.completeMaking(m); table.remove(GlassEngravingWheelMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassEngravingWheelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassEngravingWheelMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassEngravingWheelMaker.getStats() return {ironStock=GlassEngravingWheelMaker.ironStock,bronzeStock=GlassEngravingWheelMaker.bronzeStock,woodStock=GlassEngravingWheelMaker.woodStock,leatherStock=GlassEngravingWheelMaker.leatherStock,silverStock=GlassEngravingWheelMaker.silverStock,goldStock=GlassEngravingWheelMaker.goldStock,jewelStock=GlassEngravingWheelMaker.jewelStock,pearlStock=GlassEngravingWheelMaker.pearlStock,productStock=GlassEngravingWheelMaker.productStock,numBuildings=#GlassEngravingWheelMaker.buildings,hasMaker=GlassEngravingWheelMaker.maker~=nil,makerName=GlassEngravingWheelMaker.maker and GlassEngravingWheelMaker.maker.name or "—",makerSkill=GlassEngravingWheelMaker.maker and GlassEngravingWheelMaker.maker.skill or 0,activeMaking=#GlassEngravingWheelMaker.activeMaking,totalProducts=GlassEngravingWheelMaker.totalProducts} end
return GlassEngravingWheelMaker
